/* Study Hub — a fixed, expandable master question bank.
   LocalStorage is isolated behind load/save helpers so a database adapter can replace it later. */
const CATS = {
  lines: "Characters' Lines - The Odyssey",
  oxymorons: "The Bread of Salt",
  stories: "5 Selected Short Stories",
  history: "History of Greek Literature",
  gods: "Greek Gods and Goddesses",
  qualities: "Analysis - Qualities of Greek Literature",
  works: "Iliad, Odyssey, Oedipus the King"
};
const qbank = [];
const add = (id, category, topic, prompt, choices, answer, explanation, difficulty="Normal", kind="Multiple Choice") => qbank.push({id,category,topic,prompt,choices,answer,explanation,difficulty,kind});
const rows = (prefix, category, kind, data) => data.forEach(([topic,prompt,answer,explanation],i)=>add(`${prefix}-${String(i+1).padStart(3,"0")}`,category,topic,prompt,null,answer,explanation, ["Easy","Normal","Hard"][i%3],kind));

// Fixed question bank written only from the supplied notes. No generated questions are added at runtime.
