works.forEach(([topic,prompt,answer,why],i)=>{const distractors=answerPool.filter(a=>a!==answer).slice((i*3)%answerPool.length).concat(answerPool.filter(a=>a!==answer)).slice(0,3);const choices=[answer,...distractors.slice(0,3)];add(`LIT-MCQ-${String(i+1).padStart(3,"0")}`,CATS.works,topic,prompt,choices,answer,why,["Easy","Normal","Hard"][i%3],"Multiple Choice")});
